function dashboard_go(string $anchor):never{header('Location: dashboard.php#'.$anchor);exit;}
function dashboard_upload_image():?string{$file=$_FILES['image']??null;if(!$file||$file['error']===UPLOAD_ERR_NO_FILE)return null;if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024)throw new RuntimeException('الصورة يجب ألا تتجاوز 5 ميغابايت.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!@getimagesize($file['tmp_name']))throw new RuntimeException('ارفع صورة JPG أو PNG أو WebP صالحة.');$dir=__DIR__.'/uploads/products';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('تعذر إنشاء مجلد صور المنتجات.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('تعذر حفظ الصورة.');return'uploads/products/'.$name;}
function dashboard_number(mixed $value):float|false{$value=trim((string)$value);return $value===''?0.0:(is_numeric($value)&&$value>=0?(float)$value:false);}
