  if($action==='category_add'){$name=trim((string)($_POST['name']??''));$sort=max(0,min(9999,(int)($_POST['sort_order']??0)));if($name!==''&&mb_strlen($name)<=80){try{$pdo->prepare('INSERT INTO categories(name,sort_order) VALUES(?,?)')->execute([$name,$sort]);dashboard_go('categories');}catch(PDOException){$error='اسم التصنيف مستخدم بالفعل.';}}else$error='اكتب اسم تصنيف صالح.';}
  if($action==='category_toggle'){$pdo->prepare('UPDATE categories SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);dashboard_go('categories');}
  if($action==='product_add'){$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));$price=dashboard_number($_POST['price']??'');$category=(int)($_POST['category_id']??0);$sort=max(0,min(9999,(int)($_POST['sort_order']??0)));if($name===''||mb_strlen($name)>180||mb_strlen($description)>3000||$price===false){$error='تحقق من بيانات المنتج والسعر.';}else{try{$image=dashboard_upload_image();$pdo->prepare('INSERT INTO products(name,description,price,image,category_id,active,sort_order) VALUES(?,?,?,?,?,1,?)')->execute([$name,$description,$_POST['price']===''?null:$price,$image,$category?:null,$sort]);dashboard_go('store');}catch(RuntimeException $e){$error=$e->getMessage();}}}
  if($action==='product_toggle'){$pdo->prepare('UPDATE products SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);dashboard_go('store');}
  if($action==='service_add'){$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$sort=max(0,min(9999,(int)($_POST['sort_order']??0)));if($title!==''&&mb_strlen($title)<=160&&mb_strlen($description)<=3000){$pdo->prepare('INSERT INTO services(title,description,sort_order) VALUES(?,?,?)')->execute([$title,$description,$sort]);dashboard_go('services');}$error='تحقق من بيانات الخدمة.';}
  if($action==='service_toggle'){$pdo->prepare('UPDATE services SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);dashboard_go('services');}
  if($action==='coupon_add'){$code=strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',trim((string)($_POST['code']??''))));$type=(string)($_POST['discount_type']??'percent');$value=dashboard_number($_POST['discount_value']??'');$minimum=dashboard_number($_POST['minimum_total']??'');$limit=trim((string)($_POST['usage_limit']??''));if(strlen($code)<3||strlen($code)>30||!in_array($type,['percent','fixed'],true)||$value===false||$value<=0||$minimum===false||($type==='percent'&&$value>100)||($limit!==''&&(!ctype_digit($limit)||(int)$limit<1))){$error='تحقق من رمز الكوبون وقيمته.';}else{try{$pdo->prepare('INSERT INTO coupons(code,discount_type,discount_value,minimum_total,usage_limit) VALUES(?,?,?,?,?)')->execute([$code,$type,$value,$minimum,$limit===''?null:(int)$limit]);dashboard_go('coupons');}catch(PDOException){$error='رمز الكوبون مستخدم بالفعل.';}}}
  if($action==='coupon_toggle'){$pdo->prepare('UPDATE coupons SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);dashboard_go('coupons');}
