  if($action==='delivery_toggle'){$pdo->prepare('UPDATE delivery_companies SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=?')->execute([(int)($_POST['id']??0)]);dashboard_go('delivery');}
  if($action==='customer_note'){$phone=trim((string)($_POST['phone']??''));$notes=trim((string)($_POST['notes']??''));if(preg_match('/^[0-9+() .-]{7,40}$/',$phone)&&mb_strlen($notes)<=1000){$pdo->prepare('UPDATE customers SET notes=?,updated_at=CURRENT_TIMESTAMP WHERE phone=?')->execute([$notes,$phone]);dashboard_go('customers');}$error='تعذر حفظ ملاحظة العميل.';}
  if($action==='order_update'){$status=(string)($_POST['status']??'');$delivery=(int)($_POST['delivery_company_id']??0);$tracking=trim((string)($_POST['tracking_number']??''));if(in_array($status,['new','contacted','confirmed','completed','cancelled'],true)&&mb_strlen($tracking)<=120){$pdo->prepare('UPDATE orders SET status=?,delivery_company_id=?,tracking_number=? WHERE id=?')->execute([$status,$delivery?:null,$tracking,(int)($_POST['id']??0)]);dashboard_go('orders');}$error='تحقق من حالة الطلب.';}
  if($action==='settings_save'){$wa=trim((string)($_POST['whatsapp']??''));$phone1=trim((string)($_POST['phone1']??''));$phone2=trim((string)($_POST['phone2']??''));$viber=trim((string)($_POST['viber']??''));$email=trim((string)($_POST['contact_email']??''));$maps=trim((string)($_POST['maps_url']??''));$facebook=trim((string)($_POST['facebook_url']??''));$announcement=trim((string)($_POST['announcement']??''));if(!preg_match('/^[0-9]{10,15}$/',$wa)||!preg_match('/^0[0-9]{9}$/',$phone1)||!preg_match('/^0[0-9]{9}$/',$phone2)||!preg_match('/^[0-9]{10,15}$/',$viber)||!filter_var($email,FILTER_VALIDATE_EMAIL)||!filter_var($maps,FILTER_VALIDATE_URL)||!filter_var($facebook,FILTER_VALIDATE_URL)||mb_strlen($announcement)>250){$error='تحقق من وسائل الاتصال وروابط النشاط.';}else{$q=$pdo->prepare('INSERT INTO settings("key","value") VALUES(?,?) ON CONFLICT("key") DO UPDATE SET "value"=excluded."value"');foreach(['whatsapp'=>$wa,'phone1'=>$phone1,'phone2'=>$phone2,'viber'=>$viber,'contact_email'=>$email,'maps_url'=>$maps,'facebook_url'=>$facebook,'announcement'=>$announcement] as $key=>$value)$q->execute([$key,$value]);dashboard_go('settings');}}
}
$s=settings($pdo);$categories=$pdo->query('SELECT * FROM categories ORDER BY active DESC,sort_order,id')->fetchAll();$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.active DESC,p.sort_order,p.id DESC')->fetchAll();$coupons=$pdo->query('SELECT * FROM coupons ORDER BY active DESC,id DESC')->fetchAll();$delivery=$pdo->query('SELECT * FROM delivery_companies ORDER BY active DESC,id DESC')->fetchAll();$customers=$pdo->query('SELECT c.*,COUNT(o.id) order_count,COALESCE(SUM(o.total),0) spend FROM customers c LEFT JOIN orders o ON o.phone=c.phone GROUP BY c.id ORDER BY c.updated_at DESC LIMIT 100')->fetchAll();$orders=$pdo->query('SELECT o.*,d.name delivery_name FROM orders o LEFT JOIN delivery_companies d ON d.id=o.delivery_company_id ORDER BY o.id DESC LIMIT 100')->fetchAll();$services=$pdo->query('SELECT * FROM services ORDER BY active DESC,sort_order,id')->fetchAll();$newOrders=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='new'")->fetchColumn();$totalOrders=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$customerCount=(int)$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn();$sales=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status NOT IN ('cancelled')")->fetchColumn();$labels=['new'=>'جديد','contacted'=>'تم التواصل','confirmed'=>'مؤكد','completed'=>'مكتمل','cancelled'=>'ملغي'];
